"use strict";
let planetDirectoryReady=false,planetDirectoryEditable=false,planetDirectoryRevision=0,planetDirectoryBaseline='',planetDirectorySaving=false,planetDirectoryApplying=false,planetDirectoryTimer;
function canonicalDirectory(value){if(Array.isArray(value))return value.map(canonicalDirectory);if(value&&typeof value==='object')return Object.fromEntries(Object.keys(value).sort().filter(k=>value[k]!==undefined).map(k=>[k,canonicalDirectory(value[k])]));return value;}
function directorySnapshot(){const planets=state.galaxy.map(p=>({...p,publicValue:p.player?playerValue():npcValue(p),publicScore:planetScore(p),publicTick:state.tick,publicSize:p.player?totalRoids(state.roids):totalRoids(p.roids),publicPopulation:p.player?state.population:(p.population??p.publicPopulation??1000),publicXP:p.player?state.xp:(p.xp||0)})).sort((a,b)=>a.id.localeCompare(b.id));const structures=copy(state.structurePlanets).sort((a,b)=>a.id.localeCompare(b.id));const profiles=new Map([...(state.allianceDirectory||[]),state.alliance].map(a=>[a.name,a]));const alliances=[...profiles.values()].filter(a=>a.name!=='Unaffiliated').map(a=>{const v=copy(a);for(const key of ['intelRecords','intelBrowserCoords','intelTarget','intelSearch','intelGalaxyScans'])delete v[key];return v;}).sort((a,b)=>a.name.localeCompare(b.name));return {planets,structures,alliances};}
async function centralDirectoryRequest(path,body,method){const response=await fetch(path,{credentials:'same-origin',method:method||(body?'POST':'GET'),headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok){const error=Error(result.error||'The central database is unavailable.');error.status=response.status;throw error;}return result;}
function directoryStatus(message){for(const id of ['centralPlanetStatus','intelDirectoryStatus']){const el=document.getElementById(id);if(el)el.textContent=message;}}
function applySharedDirectory(data){for(const t of data.planetTypeSurveys||[])if(!PLANET_TYPES.some(p=>p.id===t.id))PLANET_TYPES.push(t);planetDirectoryApplying=true;const generation=data.resetGeneration||0;const changedUser=!!data.userId&&state.centralPlayerId!==data.userId&&(!data.canEdit||!!state.centralPlayerId);const resetChanged=generation!==(state.centralResetGeneration||0);if(resetChanged||changedUser){state=freshState();if(resetChanged)resetTickerAfterRoundReset();if(typeof midayLastSync!=='undefined')midayLastSync='';}state.centralResetGeneration=generation;state.centralPlayerOnly=!!data.playerOnly;state.centralPlayerId=data.userId;state.accountId=data.accountId;const own=data.planets.find(p=>p.player);const previousWorld=state.enrolledPlanetType||state.planetType,previousTheme=state.userSettings?.skinRace;const worldChanged=!!own&&own.planetType!==previousWorld;if(!own&&!window.isStaffWorkspace){location.href='/onboarding.html';planetDirectoryApplying=false;return;}const oldOwn=state.galaxy.find(p=>p.player);state.race=state.race||own?.race||'Terran';for(const slot of ['base','f1','f2','f3','f4'])state.fleets[slot]=normalizeFleet(state.fleets[slot]||{});state.ships=normalizeFleet(state.ships||{});state.galaxy=data.planets;if(!own&&oldOwn&&!state.galaxy.some(p=>p.id===oldOwn.id))state.galaxy.push(oldOwn);state.structurePlanets=data.structures;if(own&&(resetChanged||changedUser||state.enrolledGeneration!==generation)){for(const key of ['resources','roids','buildings','research','workforce'])if(own[key])state[key]=copy(own[key]);state.population=own.population??planetBasePopulation(own);state.biodomeDamage=own.biodomeDamage||0;state.appliedBankTrades=copy(own.bankTradeTotal||{});state.appliedEarthSalvage=copy(own.earthSalvageTotal||{});state.appliedGalaxyAid=copy(own.galaxyAidTotal||{});state.appliedPopulationTaxTotal=own.populationTaxTotal||0;state.appliedPopulationImpact=own.populationImpact?.id||'';}if(typeof applyCentralPopulationImpact==='function'&&own)applyCentralPopulationImpact(own);if(own?.planetType){state.planetType=own.planetType;if(resetChanged||changedUser||state.enrolledGeneration===undefined||state.enrolledGeneration!==generation){state.population=own.population??planetBasePopulation(own);state.race=own.race||'Terran';state.userSettings.skinRace=own.theme||'Neutral';state.enrolledGeneration=generation;}if(worldChanged){state.userSettings.skinRace=own.theme||planetTypeFor(own).theme||state.userSettings.skinRace;}state.enrolledPlanetType=own.planetType;}const myPlanet=own||oldOwn,profile=data.alliances.find(a=>a.name===myPlanet?.alliance);if(profile){const ui={intelBrowserCoords:state.alliance.intelBrowserCoords,intelTarget:state.alliance.intelTarget,intelSearch:state.alliance.intelSearch};const oldRecords=state.alliance.name===profile.name?state.alliance.intelRecords:{};state.alliance={...copy(freshState().alliance),...profile,...ui,intelRecords:oldRecords||{}};}else if(myPlanet?.alliance==='Unaffiliated'){state.alliance={...copy(freshState().alliance),name:'Unaffiliated',tag:'',members:[],applicants:[],fund:{metal:0,crystal:0,eonium:0},structures:{active:[],buildQueue:[],cooldowns:{},history:[]},fortress:{strongholdGalaxy:'',anarchyUntilTick:0},intelRecords:{},calls:[],wars:[],log:[],description:'',motd:'',message:'',recruitmentMessage:''};state.allianceCreated=false;if(typeof ownerPasskeyMemory!=='undefined')ownerPasskeyMemory='';}state.allianceDirectory=data.alliances.filter(a=>a.name!==state.alliance.name);planetDirectoryRevision=data.revision;planetDirectoryEditable=data.canEdit;planetDirectoryReady=true;update();planetDirectoryBaseline=JSON.stringify(canonicalDirectory(directorySnapshot()));planetDirectoryApplying=false;directoryStatus('CENTRAL PLANET DATABASE · CONNECTED');if(worldChanged&&previousTheme!==state.userSettings.skinRace){save();location.reload();}} 
async function initializePlanetDirectory(){try{const data=await centralDirectoryRequest('/api/planets');planetDirectoryRevision=data.revision;planetDirectoryEditable=data.canEdit;if(!data.planets.length){directoryStatus('ROUND RESET · PLANET ENROLMENT REQUIRED');if(!window.isStaffWorkspace)location.href='/onboarding.html';return;}applySharedDirectory(data);}catch(error){directoryStatus(error.message+' · local round preserved');}}
function queuePlanetDirectorySync(){if(!planetDirectoryReady||!planetDirectoryEditable||planetDirectoryApplying)return;clearTimeout(planetDirectoryTimer);planetDirectoryTimer=setTimeout(syncPlanetDirectory,750);}
async function syncPlanetDirectory(){if(planetDirectorySaving||!planetDirectoryReady||!planetDirectoryEditable||planetDirectoryApplying)return;const snapshot=directorySnapshot(),encoded=JSON.stringify(canonicalDirectory(snapshot));if(encoded===planetDirectoryBaseline)return;planetDirectorySaving=true;try{const saved=await centralDirectoryRequest('/api/planets',{revision:planetDirectoryRevision,...snapshot});planetDirectoryRevision=saved.revision;planetDirectoryBaseline=encoded;directoryStatus('CENTRAL PLANET DATABASE · SAVED');}catch(error){directoryStatus(error.message);if(error.status===409){const latest=await centralDirectoryRequest('/api/planets');applySharedDirectory(latest);notify('Another session updated the planet directory. The latest shared planets were loaded.',true);}}finally{planetDirectorySaving=false;}}
async function persistAllianceSettings(settings){if(!planetDirectoryReady)return;await syncPlanetDirectory();const data=await centralDirectoryRequest('/api/alliance-settings',{revision:planetDirectoryRevision,...settings});planetDirectoryRevision=data.revision;}
async function refreshSharedPlanets(){if(!planetDirectoryReady||planetDirectorySaving)return;try{const data=await centralDirectoryRequest('/api/planets');if((data.resetGeneration||0)!==(state.centralResetGeneration||0)){applySharedDirectory(data);return;}if(data.revision!==planetDirectoryRevision){const dirty=JSON.stringify(canonicalDirectory(directorySnapshot()))!==planetDirectoryBaseline;if(dirty&&planetDirectoryEditable){await syncPlanetDirectory();return;}applySharedDirectory(data);}}catch(error){directoryStatus(error.message);}}
initializePlanetDirectory();setInterval(()=>{if(!document.hidden)refreshSharedPlanets();},15000);

setInterval(async()=>{try{const data=await centralDirectoryRequest('/api/version');const button=document.getElementById('versionReload');if(button&&data.version!=='0.120.2')button.hidden=false;}catch{}},60000);document.addEventListener('click',e=>{if(e.target.id==='versionReload')location.reload();});
